let wins = { player: 0, ai: 0, deck: 0 };

for (let g = 0; g < 300; g++) {
  const state = e.createGame({ rng });
  e.startDuel(state);
  let steps = 0;
  while (!state.winner && steps++ < 800) {
    if (state.active === 'player') {
      const p = state.players.player;
      const choices = [];
      if (!p.summoned) {
        p.hand.forEach((inst, i) => {
          if (getCard(inst.defId).type === 'monster' && e.emptyMonsterZones(state, 'player').length) {
            choices.push(() => e.summonMonster(state, 'player', i, e.emptyMonsterZones(state, 'player')[0], rng() > 0.5 ? 'attack' : 'set'));
          }
        });
      }
      if (!p.setTrap) {
        p.hand.forEach((inst, i) => {
          if (getCard(inst.defId).type === 'trap' && e.emptySpellZones(state, 'player').length) {
            choices.push(() => e.setTrapCard(state, 'player', i, e.emptySpellZones(state, 'player')[0]));
          }
        });
      }
      p.hand.forEach((inst, i) => {
        const def = getCard(inst.defId);
        if (def.type === 'spell') {
          if (def.target === 'own') {
            const targets = e.legalSpellTargets(state, 'player', i);
            if (targets.length) choices.push(() => e.castSpell(state, 'player', i, { index: targets[0] }));
          } else if (def.target === 'enemy') {
            const targets = e.legalSpellTargets(state, 'player', i);
            if (targets.length) choices.push(() => e.castSpell(state, 'player', i, { index: targets[0] }));
          } else if (def.spellKey !== 'revive' || p.grave.some(x => getCard(x.defId).type === 'monster')) {
            choices.push(() => e.castSpell(state, 'player', i, null));
          }
        }
      });
      p.monster.forEach((inst, i) => {
        const legal = e.legalAttackTargets(state, 'player', i);
        if (legal.ok) {
          if (legal.direct) choices.push(() => e.attack(state, 'player', i, null));
          else choices.push(() => e.attack(state, 'player', i, { index: legal.indexes[0] }));
        }
        if (e.canSwitchPosition(state, 'player', i)) choices.push(() => e.switchPosition(state, 'player', i));
      });
      if (!choices.length || rng() < 0.14) {
        const res = e.endTurn(state);
        if (!res.ok) throw new Error('player endTurn failed: ' + res.error);
      } else {
        const res = choices[Math.floor(rng() * choices.length)]();
        actionsTotal++;
        if (!res.ok) throw new Error('player action failed: ' + res.error + ' step ' + steps + ' game ' + g);
      }
    } else {
      const action = nextAiAction(state);
      if (!action) {
        const res = e.endTurn(state);
        if (!res.ok) throw new Error('ai endTurn failed');
      } else {
        let res;
        if (action.kind === 'summon') res = e.summonMonster(state, 'ai', action.handIndex, action.zone, action.mode);
        else if (action.kind === 'setTrap') res = e.setTrapCard(state, 'ai', action.handIndex, action.zone);
        else if (action.kind === 'spell') res = e.castSpell(state, 'ai', action.handIndex, action.target);
        else if (action.kind === 'attack') res = e.attack(state, 'ai', action.attackerIndex, action.target);
        else throw new Error('unknown action ' + action.kind);
        actionsTotal++;
        if (!res.ok) throw new Error('ai action failed: ' + action.kind + ' ' + res.error + ' step ' + steps + ' game ' + g);
      }
    }
    if (state.players.player.lp < 0 || state.players.ai.lp < 0) throw new Error('negative lp');
    if (state.players.player.lp > 8000 || state.players.ai.lp > 8000) throw new Error('lp over max');
    if (state.players.player.hand.length > 8 || state.players.ai.hand.length > 8) throw new Error('hand overflow');
    if (state.players.player.monster.length !== 6 || state.players.ai.spell.length !== 6) throw new Error('board length');
  }
  if (!state.winner && steps >= 800) throw new Error('stall game ' + g + ' turn ' + state.turn);
  wins[state.winner]++;
  if (state.winReason === 'deck') wins.deck++;
}
console.log('OK games=300 actions=' + actionsTotal, wins);
