function playerProxy(state) {
  return { ...state, active: 'ai', players: { ai: state.players.player, player: state.players.ai } };
}
function exec(state, action, side) {
  if (action.kind === 'summon') return e.summonMonster(state, side, action.handIndex, action.zone, action.mode);
  if (action.kind === 'setTrap') return e.setTrapCard(state, side, action.handIndex, action.zone);
  if (action.kind === 'spell') return e.castSpell(state, side, action.handIndex, action.target);
  if (action.kind === 'attack') return e.attack(state, side, action.attackerIndex, action.target);
  return { ok: false, error: 'unknown' };
}

for (let g = 0; g < 500; g++) {
  const state = e.createGame({ rng });
  e.startDuel(state);
  let steps = 0;
  while (!state.winner && steps++ < 500) {
