      const act = nextAiAction(playerProxy(state));
      if (!act) { const r = e.endTurn(state); if (!r.ok) throw new Error(r.error); }
      else { const r = exec(state, act, 'player'); if (!r.ok) throw new Error('player ' + act.kind + ' ' + r.error); }
    } else {
      const act = nextAiAction(state);
      if (!act) { const r = e.endTurn(state); if (!r.ok) throw new Error(r.error); }
